  "표5_매튜헨리": [
    {"영어원문": "Thou hast them that hold the doctrine of the Nicolaitanes — the church is in danger not only from persecution from without, but from corruption from within; error spreads more quickly than truth.", "한국어번역": "니골라당의 교훈을 지키는 자들이 있도다 — 교회는 외부의 박해뿐 아니라 내부의 부패로부터도 위험하다. 오류는 진리보다 더 빨리 퍼진다.", "핵심통찰": "교회의 두 전선이 있다. 외부의 박해와 내부의 부패이다. 버가모는 두 전선 모두에서 싸우고 있었다. 내부 부패가 더 미묘하고 치명적이다"},
    {"영어원문": "Which thing I hate — Christ hates the doctrine of the Nicolaitanes, and he would have his churches hate it also; sin is still sin, though it come in the guise of Christian liberty.", "한국어번역": "내가 미워하는 것 — 그리스도는 니골라당의 교훈을 미워하신다. 그분은 그분의 교회들도 그것을 미워하기를 바라신다. 죄는 여전히 죄이다. 비록 그것이 그리스도인의 자유라는 가면을 쓰고 올지라도.", "핵심통찰": "자유의 가면을 쓴 죄가 가장 교묘하다. 은혜와 자유라는 깃발 아래 들어오는 죄가 가장 위험하다. 그리스도의 미움은 명확하다"}
  ],
  "표6_설교자료": [
    {"대지": "제목", "내용": "이와 같이 네게도 있도다, 교회 안의 발람과 니골라당", "예화_적용": "외부 바이러스를 막았어도 내부에서 자란 바이러스가 있을 수 있다. 교회의 영적 면역도 그러하다"},
    {"대지": "서론", "내용": "앞 절에서 발람의 교훈이 언급되었고 본 절에서 니골라당의 교훈이 언급된다. 그리스도는 '이와 같이'로 두 교훈의 동일성을 드러내신다. 외부의 발람과 내부의 니골라당이 같은 전략이다", "예화_적용": "다른 이름, 같은 독약이 있다. 발람과 니골라당이 그렇다"},
    {"대지": "1대지: 이와 같이 (역사의 반복)", "내용": "영적 공격은 역사를 통해 반복된다. 시대와 장소가 바뀌어도 본질은 같다. 분별은 역사적 지혜에 기초해야 한다. 과거의 거울이 현재를 비춘다", "예화_적용": "역사는 반복된다. 영적 역사도 그러하다. 어제의 발람이 오늘의 니골라당으로 나타난다"},
    {"대지": "2대지: 네게도 (교회 내부의 현실)", "내용": "교회 안에도 있다. 외부가 아니라 내부에 있다. 이것이 충격적 진단이다. 적은 성문 밖이 아니라 성 안에 있을 수 있다. 교회는 자기 내부를 감찰해야 한다", "예화_적용": "집안의 배신자가 가장 위험하다. 교회 안의 이단이 그러하다"},
    {"대지": "3대지: 니골라당 (교리의 얼굴)", "내용": "니골라당은 교리적 이름이다. 사상의 체계가 있고 교훈이 있다. 감정적 타락이 아니라 사상적 왜곡이다. 머리가 먼저 돌아가고 몸이 따라간다", "예화_적용": "잘못된 지도가 있으면 열심히 가도 잘못 간다. 잘못된 교리도 그러하다"},
    {"대지": "4대지: 지키는 자들 (고수의 문제)", "내용": "이 교훈을 지키는 자들이 있다. 잡고 놓지 않는다. 같은 크라테오 동사가 안디바에 대해서는 이름을 굳게 잡음으로, 여기서는 거짓 교훈을 굳게 잡음으로 쓰인다. 잡는 대상이 결정적이다", "예화_적용": "같은 힘으로 다른 것을 잡을 수 있다. 무엇을 잡느냐가 우리를 결정한다"},
    {"대지": "결론", "내용": "오늘 우리 교회 안에 '이와 같이'가 있는가. 외부의 박해를 견디면서 내부의 타협을 용납하지 않는가. 분별하고 권징하고 정결케 하자", "예화_적용": "오늘 교회의 내부 건강을 점검하자. 밖의 적보다 안의 적이 더 위험하다"}
  ],
